-- =====================================================================
-- Waterdrop — empty can tracking.
-- At each delivery the supplier (or delivery staff) records how many
-- empty cans were taken back for refilling. Every customer gets a running
-- "cans with customer" balance: full cans given − empty cans taken back
-- (+ a supplier correction for cans they held before using Waterdrop).
-- GENERATED by scripts/gen-migration-14.py (do not edit by hand).
-- =====================================================================

alter table public.deliveries
  add column empty_cans_collected integer not null default 0 check (empty_cans_collected between 0 and 1000);

alter table public.customers
  add column cans_out_correction integer not null default 0 check (cans_out_correction between -100000 and 100000);

-- Supplier cans currently at the customer. Internal (no access check).
create or replace function public.cans_out(p_customer_id uuid) returns integer
language sql stable security definer set search_path = public as $$
  select (select cans_out_correction from public.customers where id = p_customer_id)
       + coalesce((select sum(case d.status
                               when 'confirmed' then coalesce(d.confirmed_quantity, 0) + d.adjusted_quantity
                               when 'awaiting_confirmation' then d.actual_quantity
                               else 0 end
                             - case when d.status = 'cancelled' then 0 else d.empty_cans_collected end)
                   from public.deliveries d where d.customer_id = p_customer_id), 0)::integer;
$$;

-- Deliveries before this feature never recorded empty cans, so start every
-- existing customer at 0 cans out; the supplier sets the real count once
-- with "Correct count".
update public.customers set cans_out_correction = -public.cans_out(id)
where public.cans_out(id) <> 0;
